import { Table, StringColumn, BooleanColumn, GenericColumn, GuidColumn } from '@servicenow/sdk/core'

export const sys_ui_macro = Table({
    allowWebServiceAccess: true,
    attributes: {
        no_table_trace: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sys_metadata',
    extensible: true,
    label: 'Macro',
    name: 'sys_ui_macro',
    schema: {
        scoped_name: StringColumn({
            label: [
                {
                    hint: 'Contains the name field prefixed with the application scope if applicable.',
                    label: 'API Name',
                    plural: 'API Names',
                    language: 'en',
                },
            ],
            maxLength: 100,
            readOnly: true,
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 4000,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        media_type: StringColumn({
            label: 'Media type',
        }),
        xml: GenericColumn({
            columnType: 'xml',
            default: `<?xml version="1.0" encoding="utf-8" ?>
<j:jelly trim="false" xmlns:j="jelly:core" xmlns:g="glide" xmlns:j2="null" xmlns:g2="null">

</j:jelly>`,
            label: [
                {
                    hint: 'Must be in XML format',
                    label: 'XML',
                    plural: 'XMLs',
                    language: 'en',
                },
            ],
            maxLength: 65000,
            xmlView: true,
        }),
        category: StringColumn({
            default: 'general',
            dropdown: 'dropdown_with_none',
            label: 'Category',
        }),
        name: StringColumn({
            label: 'Name',
            mandatory: true,
            maxLength: 100,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
    textIndex: true,
})
